          caption: "วงจรผสมตัวอย่าง (ป้ายชื่อแก้ไขแล้ว)",
          alt: "วงจรผสมมีขั้ว RT สองขั้วทางซ้าย สายบน R1 5 Ω ไปจุด A แล้วต่อ R2 5 Ω ไปมุมขวาบน ลง R3 5 Ω ทางขวา แล้วกลับทางสายล่างผ่าน R4 10 Ω ถึงจุด B แล้วผ่าน R6 5 Ω กลับขั้วล่าง R5 20 Ω ต่อแนวตั้งระหว่าง A กับ B กรอบเส้นประล้อม R2 R3 R4 พร้อมข้อความ R2 + R3 + R4 อนุกรมกัน → RT1",
